export function useDebouncedSearch<T>(
  fetchFn: (query: string, signal: AbortSignal) => Promise<T[]>,
  delay = 300
) {
  const [results, setResults] = useState<T[]>([]);
  const [isPending, startTransition] = useTransition();
  const abortControllerRef = useRef<AbortController | null>(null);

  const search = (query: string) => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }
    const controller = new AbortController();
    abortControllerRef.current = controller;

    const timer = setTimeout(() => {
      fetchFn(query, controller.signal)
        .then((data) => {
          startTransition(() => {
            setResults(data);
          });
        })
        .catch((err) => {
          if (err.name !== 'AbortError') console.error(err);
        });
    }, delay);

    return () => clearTimeout(timer);
  };

  return { results, isSearching: isPending, search };
}`},docUrl:"https://reactjs.tayfunucuncu.dev/#lessons"},{id:"react-lab-2",title:u?"Lab #2: İyimser (Optimistic) State & Sepet Motoru":"Lab #2: Optimistic UI & Reactive Cart Engine",track:"reactjs",difficulty:"Advanced",chaptersCovered:u?"Bölüm 5 & 8: State Management & Performance":"Chapters 5 & 8: State Management & Performance",scenario:u?"Kullanıcı bir ürünü sepete eklediğinde sunucu yanıtını beklemeden UI'ı anında güncelleyen, sunucudan hata dönerse otomatik geri alan (rollback) bir Optimistic State motoru yazın.":"Create an Optimistic UI state manager for an e-commerce cart that instantly updates the UI, rolls back on backend failure, and uses memoized selectors.",appGoal:u?"İyimser artırma/azaltma, hata anında eski state snapshot'ına rollback yapma, localStorage senkronizasyonu ve sıfır re-render maliyeti.":"Optimistic item additions, automated state rollback on API error, localStorage persistence, and zero unnecessary re-renders.",requirements:u?["Bileşenlerin sadece dinledikleri alanlar değiştiğinde render olması için seçici (selector) deseni kullanılmalıdır.","İstek başarısız olduğunda (500/400) önceki state'e otomatik geri dönüş (rollback snapshot) yapılmalıdır.","State güncellemeleri localStorage ile senkronize tutulmalıdır.","Sepet toplam tutarı useMemo veya zustand compute ile memoize edilmelidir."]:["Use granular selector subscriptions to prevent whole-tree re-renders.","Store snapshot of previous state to rollback automatically on mutation failure.","Persist state to localStorage with hydration safety.","Memoize total calculations to avoid recalculation on unrelated updates."],starterSnippet:{fileName:"cartStore.ts",language:"typescript",code:`// GÖREV: Optimistic cart store tasarımı
